import { useEffect, useState, useCallback } from "react";
import Home from "@/pages/Home";
import OBSDisplay from "@/pages/OBSDisplay";
import SongSelector from "@/pages/SongSelector";

function getPageFromPath(): 'home' | 'obs' | 'selector' {
  const path = window.location.pathname;
  if (path === "/obs" || window.location.search.includes("obs=1")) {
    return 'obs';
  } else if (path === "/selector") {
    return 'selector';
  }
  return 'home';
}

export default function App() {
  const [page, setPage] = useState<'home' | 'obs' | 'selector'>(getPageFromPath);

  useEffect(() => {
    const handlePopState = () => {
      setPage(getPageFromPath());
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  const handleSwitchPage = useCallback((target: 'home' | 'selector') => {
    const path = target === 'selector' ? '/selector' : '/';
    window.history.pushState({}, '', path);
    setPage(target);
  }, []);

  return (
    <>
      <div style={{ display: page === 'home' ? 'block' : 'none' }}>
        <Home onSwitchPage={handleSwitchPage} />
      </div>
      <div style={{ display: page === 'selector' ? 'block' : 'none' }}>
        <SongSelector onSwitchPage={handleSwitchPage} />
      </div>
      {page === 'obs' && <OBSDisplay />}
    </>
  );
}
